namespace {
unsigned checks=0;
void need(bool b,const char* why){if(!b)throw std::runtime_error(why);++checks;}
template<class F>void rejects(F f,const char* why){bool bad=false;try{f();}catch(const std::exception&){bad=true;}need(bad,why);}
struct Scratch {fs::path parent=fs::canonical(fs::temp_directory_path());fs::path path=parent/("aibs-content-v3-"+new_uuid());Scratch(){fs::create_directory(path);}~Scratch(){std::error_code e;if(path.parent_path()==parent&&path.filename().string().starts_with("aibs-content-v3-"))fs::remove_all(path,e);}};
void write(const fs::path& p,std::span<const std::byte> b){std::ofstream f(p,std::ios::binary);f.write(reinterpret_cast<const char*>(b.data()),static_cast<std::streamsize>(b.size()));f.close();need(f.good(),"Fixture write");}
void write(const fs::path& p,const std::string& s){write(p,{reinterpret_cast<const std::byte*>(s.data()),s.size()});}
FirstBootContent original(){CreatorSession s(first_boot_schema(),"v3-proof","main");need(seed_first_boot(s).ok,"Seed");return FirstBootContent::from_template(s);}
FirstBootContentDefinition modern(const FirstBootContent& c){auto d=c.definition();d.format_version=3;d.asset_profile=AssetContentProfile::warm_beginning;d.exposure=1.25f;
 const auto baseline=first_boot_content_baseline(c);const GameplayStoreRecovery state{{"v3-proof",d.world_id,"main",new_uuid(),GameplayContext::temporary_play},baseline.revision,baseline.sequence,baseline.components};
 GroundedCharacter settled(first_boot_content_scene(state,c),d.jenison_returns.front());for(unsigned i=0;i<32;++i)settled.advance({},1.0/60);need(settled.state().grounded,"Reference companion spawn settles on actual closed-world ground");
 FirstBootCompanionBinding a;a.entity_id=new_uuid();a.name="Adam";a.spawn=settled.state().feet;a.routes.nodes={{"nook",a.spawn},{"approach",{a.spawn.x+2,a.spawn.y,a.spawn.z}}};a.routes.edges={{"nook","approach","main",true}};d.companions.push_back(a);
 FirstBootLightDefinition l;l.entity_id=new_uuid();l.name="Nook reserve";l.position={-32,3,-25};l.direction={0,-1,0};l.color={1,.65f,.25f};l.intensity=2;l.radius=8;d.lights.push_back(l);return d;}
AssetPackReference pack(const fs::path& source,const fs::path& store){fs::create_directory(source);auto a=import_surface_obj("v 0 0 0\nv 1 0 0\nv 0 1 0\nvt 0 0\nvt 1 0\nvt 0 1\nf 1/1 2/2 3/3\n",std::vector<MeshMaterial>{{"pcb",{1,1,1},0}},new_uuid(),"PCB",ObjUvOrigin::top_left);a.images={{ImageSemantic::srgb_color,{{1,1,{10,100,30,255}}}}};a.albedo_images={0};const auto bytes=encode_surface_asset(a);const auto sha=asset_sha256(bytes);write(source/(sha+".aibsurf"),bytes);write(source/"catalog.aibcat",std::string("AIBCAT 2\nsurface ")+a.geometry.asset_id+" "+sha+" "+sha+".aibsurf\n");write(source/"LICENSE.txt",std::string("Original synthetic test asset\n"));write(source/"provenance.json",std::string("{}\n"));return adopt_asset_pack(source,store);}
ContentEditRequest request(const ContentAuthoringHost& h,std::vector<ContentEdit> e){const auto s=h.snapshot();return {new_uuid(),s->revision,s->content.fingerprint(),"v3 preservation",std::move(e)};}
void metadata(const FirstBootContent& c,const FirstBootContentDefinition& expected){const auto& d=c.definition();need(d.format_version==3&&d.asset_profile==AssetContentProfile::warm_beginning&&d.exposure==expected.exposure,"Modern profile/exposure retained");need(d.companions.size()==1&&d.companions[0].entity_id==expected.companions[0].entity_id&&d.companions[0].routes.nodes.size()==2&&d.companions[0].routes.edges[0].door=="main","Companion and authored routes retained");need(d.lights.size()==1&&d.lights[0].entity_id==expected.lights[0].entity_id&&d.lights[0].intensity==2,"Light binding retained");need(d.initial_records.size()==6,"Six legacy initial records retained");}
}
int main(){try{
 const auto v1=original();const auto v1bytes=first_boot_content_encode(v1);need(first_boot_content_encode(first_boot_content_decode(v1bytes))==v1bytes,"v1 bytes retained");auto v2def=v1.definition();v2def.format_version=2;const auto v2=FirstBootContent::create(v2def);const auto v2bytes=first_boot_content_encode(v2);need(first_boot_content_encode(first_boot_content_decode(v2bytes))==v2bytes,"v2 bytes retained");auto v2oracle=v1bytes;v2oracle[4]=2;v2oracle.insert(v2oracle.end(),4,0);need(v2bytes==v2oracle,"Empty AIBD2 remains frozen legacy fields plus placement count");
 auto d=modern(v1);const auto c=FirstBootContent::create(d);const auto encoded=first_boot_content_encode(c);need(encoded[4]==3&&first_boot_content_encode(first_boot_content_decode(encoded))==encoded,"Canonical v3 roundtrip");metadata(first_boot_content_decode(encoded),d);
 const auto extension=v2bytes.size();need(encoded.size()>extension&&std::equal(v2bytes.begin()+6,v2bytes.end(),encoded.begin()+6),"v3 retains v2 field order before extension");
 auto malformed=encoded;malformed[extension]=255;rejects([&]{first_boot_content_decode(malformed);},"Unknown asset profile byte");
 malformed=encoded;malformed.push_back(0);rejects([&]{first_boot_content_decode(malformed);},"Trailing v3 bytes");
 for(std::size_t n=0;n<encoded.size();n+=127)rejects([&]{first_boot_content_decode(std::span(encoded).first(n));},"Truncated v3 definition");
 for(std::size_t n=encoded.size()-16;n<encoded.size();++n)rejects([&]{first_boot_content_decode(std::span(encoded).first(n));},"Truncated v3 tail");
 malformed=encoded;const auto noncanonical=std::bit_cast<std::uint64_t>(1.1);for(unsigned i=0;i<8;++i)malformed[extension+1+i]=static_cast<unsigned char>((noncanonical>>(i*8))&255);rejects([&]{first_boot_content_decode(malformed);},"Non-float-representable exposure wire value");
 malformed=encoded;malformed[extension+9]=2;rejects([&]{first_boot_content_decode(malformed);},"Companion count bound before allocation");
 auto bad=d;bad.format_version=2;rejects([&]{FirstBootContent::create(bad);},"No modern fields hidden in v2");bad=d;bad.exposure=std::numeric_limits<float>::infinity();rejects([&]{FirstBootContent::create(bad);},"Finite exposure");bad=d;bad.exposure=0;rejects([&]{FirstBootContent::create(bad);},"Positive exposure");bad=d;bad.companions[0].entity_id=d.lights[0].entity_id;rejects([&]{FirstBootContent::create(bad);},"Cross-family identity collision");bad=d;bad.companions[0].routes.edges[0].to="missing";rejects([&]{FirstBootContent::create(bad);},"Broken authored route");bad=d;bad.lights[0].direction={0,0,0};rejects([&]{FirstBootContent::create(bad);},"Nonzero light direction");
 bad=d;for(const auto& r:d.initial_records)if(r.type_id=="firstboot.Door"&&std::get<std::string>(r.fields.at("role"))=="main")bad.companions[0].spawn={static_cast<float>(std::get<double>(r.fields.at("x"))),static_cast<float>(std::get<double>(r.fields.at("y"))-std::get<double>(r.fields.at("half_y"))),static_cast<float>(std::get<double>(r.fields.at("z")))};rejects([&]{FirstBootContent::create(bad);},"Companion cannot spawn inside an initially closed door");
 auto downgrading=v1.definition();downgrading.revision=1;need(first_boot_content_preview(c,downgrading).status==FirstBootContentPreviewStatus::rejected,"Preview cannot downgrade content version");
 auto moved=d;moved.revision=1;moved.lights[0].intensity=3;const auto preview=first_boot_content_preview(c,moved);need(preview.status==FirstBootContentPreviewStatus::new_play_branch&&preview.render_rebuild&&std::find(preview.affected_ids.begin(),preview.affected_ids.end(),d.lights[0].entity_id)!=preview.affected_ids.end(),"Light preview declares render dependency/new save branch");
 auto media=d;FirstBootMemoryBinding memory;memory.entity_id=new_uuid();memory.name="Optional podium memory";memory.position=d.jenison_returns.front();memory.audio={new_uuid(),std::string(64,'a'),std::string(64,'b')};media.memories.push_back(memory);const auto media_content=FirstBootContent::create(media);need(first_boot_content_decode(first_boot_content_encode(media_content)).definition().memories[0].audio==memory.audio,"Media identity binding roundtrip");
 Scratch scratch;fs::create_directory(scratch.path/"store");const auto store=scratch.path/"store";const auto ref=pack(scratch.path/"source",store);
 ContentAuthoringHost host(c,"v3-proof","main");host.bind_asset_store(store);const auto id=new_uuid();FirstBootAssetPlacement p{id,"Textured placed part",ref.asset_id,ref.asset_sha256,ref.pack_sha256,{-20,2,-20},{1,1,1},{},true};
 auto q=request(host,{ContentCreateAssetPlacement{p}});const auto accepted=host.apply(host.snapshot()->scope,q);need(accepted.status==ContentAuthoringStatus::applied,"Modern surface placement accepted");metadata(host.snapshot()->content,d);need(host.snapshot()->content.definition().placements.size()==1,"Placement exists");
 auto head=host.snapshot();need(host.travel(head->scope,{new_uuid(),head->revision,head->content.fingerprint(),false}).status==ContentAuthoringStatus::undone,"Undo");metadata(host.snapshot()->content,d);need(host.snapshot()->content.definition().placements.empty(),"Undo placement");head=host.snapshot();need(host.travel(head->scope,{new_uuid(),head->revision,head->content.fingerprint(),true}).status==ContentAuthoringStatus::redone,"Redo");metadata(host.snapshot()->content,d);
 const auto path=scratch.path/"chapter.aiba";need(host.save(path).status==ContentAuthoringStatus::saved,"Save modern chapter");auto reopened=ContentAuthoringHost::open(path,"v3-proof","main");reopened.bind_asset_store(store);metadata(reopened.snapshot()->content,d);need(reopened.snapshot()->content.fingerprint()==host.snapshot()->content.fingerprint(),"Exact restart fingerprint");auto change=request(reopened,{ContentSetField{id,"name",std::string("Edited after restart")}});need(reopened.apply(reopened.snapshot()->scope,change).status==ContentAuthoringStatus::applied,"Edit modern placement after restart");metadata(reopened.snapshot()->content,d);need(reopened.save(path).status==ContentAuthoringStatus::saved,"Save after restart");
 ContentAuthoringHost legacy(v2,"v3-proof","main");legacy.bind_asset_store(store);need(legacy.preview(legacy.snapshot()->scope,request(legacy,{ContentCreateAssetPlacement{p}})).status==ContentAuthoringStatus::rejected,"Legacy profile cannot admit surface");
 ContentAuthoringHost unsupported(media_content,"v3-proof","main");unsupported.bind_asset_store(store);need(unsupported.save(scratch.path/"unsupported.aiba").status==ContentAuthoringStatus::rejected,"Unimplemented audio loader never ignored");need(!fs::exists(scratch.path/"unsupported.aiba"),"No partial unsupported save");
 std::cout<<"PASS: "<<checks<<" v3 canonical/version/metadata/history/typed-dependency checks\n";return 0;
 }catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
